/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CASE_HEADER
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CASE   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 3 emitted of 3 (one per source view AND run)
   runs        : 2 -- opus_health_delta3, opus_health_legacy_v4
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CASE_HK
   hashdiff    : SAT_CASE_HEADER_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
   DECLARED SOURCE PRECEDENCE -- 2 attribute(s) are written by BOTH runs.
   Never a key change and never RECORD_SOURCE in a key: either would
   silently alter grain. Precedence is a VALUE choice, reversible by reload:
     ALLOCATION_INDICATOR                         opus_health_legacy_v4 > opus_health_delta3
     ALLOCATION_DATE                              opus_health_legacy_v4 > opus_health_delta3
*/

with feeders as (
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__ALLOCATE_ID))) as HUB_CASE_HK
        , ALLOCATE_FLAG as ALLOCATION_INDICATOR
        , ALLOCATE_ON as ALLOCATION_DATE
        , cast(null as varchar) as QUERY_RESPONSE_TEXT
        , 'BJAZ_HM_INWARD_AUTOALLOCATION' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_inward_autoallocation') }}
    where (nullif(trim(ALLOCATE_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__QUERY_REF_ID))) as HUB_CASE_HK
        , cast(null as varchar) as ALLOCATION_INDICATOR
        , cast(null as varchar) as ALLOCATION_DATE
        , QUERY_REPLY as QUERY_RESPONSE_TEXT
        , 'BJAZ_HM_PREAUTH_QUERY' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_preauth_query') }}
    where (nullif(trim(QUERY_REF_ID),'')) is not null
    union all
    select
        md5(upper('HUB_CASE|' || (HUB_CASE_BK__INWARDNO))) as HUB_CASE_HK
        , ALLOCATE_FLAG as ALLOCATION_INDICATOR
        , ALLOCATE_ON as ALLOCATION_DATE
        , cast(null as varchar) as QUERY_RESPONSE_TEXT
        , 'NG_FAX_INWARD_DETAILS' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ng_fax_inward_details') }}
    where (nullif('INWARD:' || nullif(trim(INWARDNO),''), 'INWARD:')) is not null
),

resolved as (
    select
        HUB_CASE_HK,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ALLOCATION_INDICATOR end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ALLOCATION_INDICATOR end)) as ALLOCATION_INDICATOR,
        coalesce(max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ALLOCATION_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then ALLOCATION_DATE end)) as ALLOCATION_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then QUERY_RESPONSE_TEXT end) as QUERY_RESPONSE_TEXT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CASE_HK
),

hashed as (
    select
        *,
        case when ALLOCATION_INDICATOR is not null or ALLOCATION_DATE is not null or QUERY_RESPONSE_TEXT is not null
                     then md5(upper(coalesce(cast(ALLOCATION_INDICATOR as varchar), '') || '|' || coalesce(cast(ALLOCATION_DATE as varchar), '') || '|' || coalesce(cast(QUERY_RESPONSE_TEXT as varchar), '')))
                end as SAT_CASE_HEADER_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CASE_HK is not null
  and SAT_CASE_HEADER_HASHDIFF is not null
